return items.map(item => {
  const a = item.json;
  let sourceUrl = "";

  try {
    // 📰 Extract true article URL from the content field (the <a href=""> tag)
    if (a.content && a.content.includes('<a href="')) {
      const match = a.content.match(/<a href="([^"]+)"/);
      if (match && match[1]) {
        const decoded = decodeURIComponent(match[1]);
        const innerMatch = decoded.match(/https?:\/\/(?!news\.google\.com)[^"&]+/);
        sourceUrl = innerMatch && innerMatch[0] ? innerMatch[0] : decoded;
      }
    } else if (a.link && a.link.includes("news.google.com")) {
      // fallback if no content tag
      const decoded = decodeURIComponent(a.link);
      const innerMatch = decoded.match(/https?:\/\/(?!news\.google\.com)[^"&]+/);
      sourceUrl = innerMatch && innerMatch[0] ? innerMatch[0] : decoded;
    } else {
      sourceUrl = a.link || "";
    }
  } catch (e) {
    sourceUrl = a.link || "";
  }

  // 🌏 Improved region detection
  let region = "Global";
  try {
    let hostname = new URL(sourceUrl).hostname.toLowerCase();
    hostname = hostname.replace(/^(www\.|m\.|amp\.)/, "");

    if (hostname.includes(".com.au") || hostname.includes(".gov.au") || hostname.includes(".org.au")) {
      region = "AU";
    } else if (hostname.includes(".co.uk") || hostname.includes(".gov.uk") || hostname.includes(".org.uk")) {
      region = "UK";
    } else if (hostname.endsWith(".ca")) region = "CA";
    else if (hostname.endsWith(".fr")) region = "FR";
    else if (hostname.endsWith(".de")) region = "DE";
    else if (hostname.endsWith(".eu")) region = "EU";
    else if (hostname.endsWith(".in")) region = "IN";
    else if (hostname.endsWith(".sg")) region = "SG";
    else if (hostname.endsWith(".nz")) region = "NZ";
    else if (hostname.endsWith(".jp")) region = "JP";
    else if (
      hostname.includes("europa") ||
      hostname.includes("europe") ||
      hostname.includes("eurlex") ||
      hostname.includes("eu-parliament")
    ) {
      region = "EU";
    } else {
      const tld = hostname.split(".").pop().toUpperCase();
      region = ["COM", "ORG", "NET", "EDU"].includes(tld) ? "Global" : tld;
    }
  } catch (e) {}

  return {
    json: {
      headline: a.title || "Untitled",
      date: a.pubDate || a.isoDate || "",
      source: sourceUrl,
      region,
      sentiment: "pending"
    }
  };
});

const raw = items[0].json.data ? JSON.parse(items[0].json.data) : {};
const articles = raw.articles || [];

function formatGDELTDate(seendate) {
  // GDELT gives e.g. 20251028T221500Z — convert manually
  if (!seendate || typeof seendate !== 'string' || seendate.length < 15) return "Unknown";

  try {
    const year = seendate.slice(0, 4);
    const month = seendate.slice(4, 6);
    const day = seendate.slice(6, 8);
    const hour = seendate.slice(9, 11);
    const minute = seendate.slice(11, 13);
    const second = seendate.slice(13, 15);

    // Return Google Sheets–friendly timestamp
    return `${year}-${month}-${day} ${hour}:${minute}:${second}`;
  } catch (e) {
    return "Unknown";
  }
}

return articles.map(a => ({
  json: {
    headline: a.title || "Untitled",
    date: formatGDELTDate(a.seendate),
    source: a.url || "",
    region: a.sourcecountry || "Global",
    sentiment: "pending"
  }
}));

// n8n provides input data via the variable 'items'
const results = [];

for (const item of $input.all()) {
  const output = item.json.output?.[0]?.content?.[0]?.text || {};
  results.push({
    json: {
      headline: item.json.headline,
      date: item.json.date,
      source: item.json.source,
      region: item.json.region,
      tone: output.tone || "unknown",
      topics: Array.isArray(output.topics) ? output.topics.join(", ") : ""
    }
  });
}

return results;
